const rl = readline.createInterface({
  input: process.stdin,
  output: null,
  terminal: false
});

const lines = [];
rl.on('line', (line) => {
  lines.push(line);
});

rl.on('close', () => {
  try {
    const result = processElection(lines, mode);
    process.stdout.write(result);
    process.exit(0);
  } catch (err) {
    process.stderr.write(err.message + '\n');
    process.exit(2);
  }
});

function error(lineNum, message) {
  if (lineNum === null) {
    throw new Error(`error: ${message}`);
  }
  throw new Error(`error: line ${lineNum}: ${message}`);
}

function processElection(inputLines, mode) {
  // Parse input
  const parsedLines = [];
  for (let i = 0; i < inputLines.length; i++) {
    let line = inputLines[i].trim();

    // Drop trailing empty line if present
    if (i === inputLines.length - 1 && line === '') {
      break;
    }

    // Skip empty lines and comments
    if (line === '' || line.startsWith('#')) {
      continue;
    }

    // Split on whitespace
    const parts = line.split(/\s+/);
    parsedLines.push({ lineNum: i + 1, parts });
  }

  // Process the parsed lines
  let candidates = null;
  let ballots = [];
  let candidatesLineNum = null;
  let ballotsStarted = false;

  for (const { lineNum, parts } of parsedLines) {
    if (parts.length === 0) continue;

    const directive = parts[0];

    if (directive === 'candidates') {
      if (candidates !== null) {
        error(lineNum, 'candidates must be declared once, before any ballot');
      }
      if (ballotsStarted) {
        error(lineNum, 'candidates must be declared once, before any ballot');
      }
      if (parts.length < 2) {
        error(lineNum, 'expected candidates <name>...');
      }

      const nameSet = new Set();
      const nameList = [];
      for (let i = 1; i < parts.length; i++) {
        const name = parts[i];
        if (!isValidName(name)) {
          error(lineNum, `invalid candidate name ${name}`);
        }
        if (nameSet.has(name)) {
          error(lineNum, `candidate ${name} is declared twice`);
        }
        nameSet.add(name);
        nameList.push(name);
      }
      candidates = nameList;
      candidatesLineNum = lineNum;
    } else if (directive === 'ballot') {
      if (candidates === null) {
        error(lineNum, 'candidates must be declared once, before any ballot');
      }
      ballotsStarted = true;

      if (parts.length < 2) {
        error(lineNum, 'expected ballot <count> <candidate>...');
      }

      const countStr = parts[1];
      const count = parseCount(countStr);
      if (count === null) {
        error(lineNum, 'count must be a positive integer');
      }

      if (parts.length < 3) {
        error(lineNum, 'expected ballot <count> <candidate>...');
      }

      const candidateSet = new Set();
      const ranking = [];
      for (let i = 2; i < parts.length; i++) {
        const name = parts[i];
        if (!candidates.includes(name)) {
          error(lineNum, `unknown candidate ${name}`);
        }
        if (candidateSet.has(name)) {
          error(lineNum, `candidate ${name} is repeated`);
        }
        candidateSet.add(name);
        ranking.push(name);
      }
      ballots.push({ count, ranking });
    } else {
      error(lineNum, `unknown directive ${directive}`);
    }
  }

  if (candidates === null) {
    error(null, 'no candidates');
  }

  // Run the election
  return runElection(candidates, ballots, mode);
}

function isValidName(name) {
  const validChars = /^[A-Za-z0-9_-]+$/;
  return validChars.test(name);
}

function parseCount(countStr) {
  // Must be positive integer without sign or leading zero
  if (countStr === '' || /^0/.test(countStr) || /[^0-9]/.test(countStr)) {
    return null;
  }
  const count = parseInt(countStr, 10);
  return count > 0 ? count : null;
}

function runElection(candidates, ballots, mode) {
  // Initialize state
  const continuing = new Set(candidates);
  const roundResults = [];
  let roundNum = 0;

  while (true) {
    roundNum++;
    const votes = countRound(candidates, ballots, continuing);
    roundResults.push(votes);

    // Calculate active total
    const activeTotal = Object.values(votes).filter(v => v > 0).reduce((a, b) => a + b, 0) + votes.exhausted;

    // Check for winner
    let winner = null;
    for (const candidate of candidates) {
      if (votes[candidate] * 2 > activeTotal) {
        winner = candidate;
        break;
      }
    }

    // Check for no winner (no active votes)
    if (activeTotal === 0 && winner === null) {
      // No winner
      if (mode === 'rounds') {
        let output = `round ${roundNum}: `;
        const sortedCandidates = sortByVotes(candidates, votes);
        output += sortedCandidates.map(c => `${c}=${votes[c]}`).join(' ');
        output += ` exhausted=${votes.exhausted}\n`;
        let result = output;
        result += 'no winner\n';
        return result;
      } else {
        return `rounds ${roundNum}\nno winner\n`;
      }
    }

    if (winner !== null) {
      // Election ends
      if (mode === 'rounds') {
        let output = `round ${roundNum}: `;
        const sortedCandidates = sortByVotes(candidates, votes);
        output += sortedCandidates.map(c => `${c}=${votes[c]}`).join(' ');
        output += ` exhausted=${votes.exhausted}\n`;
        let result = output;
        result += `winner ${winner}\n`;
        return result;
      } else {
        return `rounds ${roundNum}\nwinner ${winner}\n`;
      }
    }

    // Output for rounds mode
    if (mode === 'rounds') {
      let output = `round ${roundNum}: `;
      const sortedCandidates = sortByVotes(candidates, votes);
      output += sortedCandidates.map(c => `${c}=${votes[c]}`).join(' ');
      output += ` exhausted=${votes.exhausted}\n`;
      process.stdout.write(output);
    }

    // Eliminate a candidate
    const toEliminate = findCandidateToEliminate(candidates, continuing, roundResults);
    if (mode === 'rounds') {
      process.stdout.write(`eliminated ${toEliminate}\n`);
    }
    continuing.delete(toEliminate);
  }
}

function countRound(candidates, ballots, continuing) {
  const votes = {};
  for (const candidate of candidates) {
    votes[candidate] = 0;
  }
  votes.exhausted = 0;

  for (const ballot of ballots) {
    let counted = false;
    for (const candidate of ballot.ranking) {
      if (continuing.has(candidate)) {
        votes[candidate] += ballot.count;
        counted = true;
        break;
      }
    }
    if (!counted) {
      votes.exhausted += ballot.count;
    }
  }

  return votes;
}

