  const sorted = candidates.slice();
  sorted.sort((a, b) => {
    if (votes[b] !== votes[a]) {
      return votes[b] - votes[a]; // Descending by votes
    }
    return a.localeCompare(b); // Ascending by name
  });
  return sorted;
}

function findCandidateToEliminate(candidates, continuing, roundResults) {
  const continuingArray = Array.from(continuing);

  // Find candidates with fewest votes in current round
  const currentRound = roundResults[roundResults.length - 1];
  const minVotes = Math.min(...continuingArray.map(c => currentRound[c]));
  let candidates_with_min = continuingArray.filter(c => currentRound[c] === minVotes);

  if (candidates_with_min.length === 1) {
    return candidates_with_min[0];
  }

  // Tiebreaker: compare across all rounds
  for (let round = 0; round < roundResults.length; round++) {
    const roundVotes = roundResults[round];
    const minRoundVotes = Math.min(...candidates_with_min.map(c => roundVotes[c]));
    const survivors = candidates_with_min.filter(c => roundVotes[c] === minRoundVotes);

    if (survivors.length === 1) {
      return survivors[0];
    }

    candidates_with_min = survivors;
  }

  // Still tied: eliminate whose name sorts last by code point
  candidates_with_min.sort((a, b) => b.localeCompare(a));
  return candidates_with_min[0];
}
